#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;int n=s.size();
vector<long long>dp(n+1,0);
dp[0]=1;
dp[1]=(s[0]=='0')?0:1;
for(int i=2;i<=n;++i){
int one=s[i-1]-'0',two=stoi(s.substr(i-2,2));
if(one>=1&&one<=9)dp[i]+=dp[i-1];
if(two>=10&&two<=26)dp[i]+=dp[i-2];}
printf("%lld\n",dp[n]);return 0;}

